        if (!j.rooms.length) {
          list.innerHTML = '<div class="muted">No active rooms \u2014 create one by joining any room name.</div>';
          return;
        }
        list.innerHTML = j.rooms.map((r4) => `<button class="room" data-room="${esc3(r4.name)}"><b>${esc3(r4.name)}</b><span>${esc3(r4.cfg.mapName || "Citadel")} \xB7 ${r4.humans} player${r4.humans === 1 ? "" : "s"} \xB7 ${r4.bots} bots</span><span>${r4.score.T}\u2013${r4.score.CT} \xB7 round ${r4.round}</span></button>`).join("");
